void processIDCMP(void) {
	while(!DONE) {
		Wait(1L << win->UserPort->mp_SigBit);
		msg = GT_GetIMsg(win->UserPort);
		GT_ReplyIMsg(msg);
		if(msg->Class == IDCMP_CLOSEWINDOW) DONE = TRUE;
	};
};

void closeAll() {
	if(win) CloseWindow(win);
};

int main() {
	win = OpenWindow(&winLayout);

	while(!DONE) processIDCMP();

	closeAll();



	return 0;
};

